26	/** inserted into match06.ts FRAG before main(); only compiled where the material defines W30 */
27	export const W30_GLSL = /* glsl */ `
28	#ifdef W30
29	uniform sampler2D uW30T;
30	uniform vec4 uW30A; // flow speed (u/s), vein strength, rainbow strength, glint strength
31	uniform vec4 uW30B; // vein tile across (u), along (u), ripple strength, share of the old painted strip kept
32	uniform vec4 uW30C; // start hand-over a..b (camera distance from the approved viewpoint), rainbow band inner / outer edge (|l| / Wc)
33	// display-space colour across the slide, x = |lateral| / Wc (0 centre .. 1 at the foam), read from the storyboard panels and the approved
34	// picture: bright cyan centre -> azure -> blue-violet -> magenta -> hot pink -> lilac-pink at the bank. k = how much of the iridescent
35	// RAINBOW strip shows in the edge band (the approved right-hand band measured across it: cyan, mint, yellow, peach, pink, magenta)
36	vec3 w30Lat(float x, float k) {
37	  vec3 c = vec3(0.14, 0.85, 1.0);
38	  c = mix(c, vec3(0.02, 0.74, 0.99), smoothstep(0.05, 0.28, x));
39	  c = mix(c, vec3(0.03, 0.53, 0.95), smoothstep(0.28, 0.44, x));
40	  vec3 p = mix(c, vec3(0.45, 0.36, 0.97), smoothstep(0.44, 0.56, x));
41	  p = mix(p, vec3(0.92, 0.27, 0.90), smoothstep(0.54, 0.68, x));
42	  p = mix(p, vec3(0.99, 0.45, 0.88), smoothstep(0.68, 0.82, x));
43	  p = mix(p, vec3(0.96, 0.62, 0.95), smoothstep(0.82, 0.93, x));
44	  p = mix(p, vec3(0.90, 0.32, 0.92), smoothstep(0.93, 1.0, x));
45	  vec3 r = mix(c, vec3(0.05, 0.84, 0.99), smoothstep(0.40, 0.50, x));
46	  r = mix(r, vec3(0.45, 0.93, 0.80), smoothstep(0.50, 0.58, x));
47	  r = mix(r, vec3(0.98, 0.93, 0.55), smoothstep(0.58, 0.66, x));
48	  r = mix(r, vec3(0.99, 0.70, 0.62), smoothstep(0.66, 0.74, x));
49	  r = mix(r, vec3(0.98, 0.42, 0.86), smoothstep(0.74, 0.84, x));
50	  r = mix(r, vec3(0.92, 0.26, 0.90), smoothstep(0.84, 0.97, x));
51	  return mix(p, r, k);
52	}
53	vec3 w30Water(vec3 old, vec2 ls, float wc, float t, float dAp, float fres) {
54	  float u = ls.x / wc, sd = u < 0.0 ? -1.0 : 1.0;
55	  float sf = ls.y - t * uW30A.x; // anchored to the river, flowing downstream (+s)
56	  // soft, broad flow lines (the vein tile read blurred = mip-biased, long along the flow): they bend the colour bands and give the
57	  // body light / deep zones (volume) without any thin scratch lines
58	  float body = texture2D(uW30T, vec2(ls.x / 1.3 + 0.37, sf / 7.5 + 0.11), 2.5).r;
59	  // the colour bands follow the river but meander gently and drift with the flow (flowing curves, not parallel stripes)
60	  float mu = 0.09 * sin(ls.y * 0.17 + t * 0.35) + 0.05 * sin(ls.y * 0.43 + 1.1) + 0.10 * (body - 0.15);
61	  float x = abs(u + mu * (1.0 - 0.5 * abs(u)));
62	  float rk = smoothstep(-0.3, 0.6, sin(ls.y * 0.11 + sd * 2.3) + 0.5 * sin(ls.y * 0.29 + 0.7)) * clamp(uW30A.z, 0.0, 1.0);
63	  float ew = mix(1.0, (x - uW30C.z) / max(uW30C.w - uW30C.z, 1e-3), step(0.0, uW30C.w)); // band placement (w30e)
64	  vec3 col = w30Lat(clamp(uW30C.z + ew * (1.0 - uW30C.z) * step(uW30C.z, x) + x * step(x, uW30C.z) - uW30C.z * step(uW30C.z, x) * 0.0, 0.0, 1.0), rk);
65	  col *= 0.86 + 0.32 * smoothstep(0.02, 0.4, body);
66	  // volume: brighter crown, slightly deeper just inside the banks
67	  col += vec3(0.10, 0.10, 0.06) * (1.0 - smoothstep(0.0, 0.35, x));
68	  col *= 1.0 - 0.10 * smoothstep(0.86, 1.0, x);
69	  // electric veins: crisp sparse white lightning (R) + branching crackle net (G) from two reads at different scale / speed,
70	  // flickering like current; a soft glow round them; white-cyan on the water, pink-white on the pink bands
71	  vec2 q1 = vec2(ls.x / uW30B.x, sf / uW30B.y);
72	  vec2 q2 = vec2(ls.x / (uW30B.x * 0.62) + 0.31 + 0.04 * sin(sf * 0.35), (ls.y - t * uW30A.x * 1.4) / (uW30B.y * 0.68) + 0.57);
73	  vec3 a = texture2D(uW30T, q1).rgb;
74	  vec3 b = texture2D(uW30T, q2).rgb;
75	  float fl = 0.72 + 0.28 * sin(t * 5.3 + sf * 1.7 + ls.x * 0.9);
76	  float glow = smoothstep(0.10, 0.55, max(a.r * fl, b.g)) * uW30A.y;
77	  float vein = clamp(max(smoothstep(0.60, 0.92, a.r * fl), 0.85 * smoothstep(0.50, 0.88, b.g)) * uW30A.y, 0.0, 1.0);
78	  float pinkS = smoothstep(0.55, 0.75, x) * (1.0 - rk * 0.5);
79	  vec3 vc = mix(vec3(0.84, 1.0, 1.0), vec3(1.0, 0.80, 0.98), pinkS);
80	  col = mix(col, mix(col, vec3(0.30, 0.92, 1.0), 1.0 - pinkS) + vec3(0.12) * pinkS, glow * 0.45);
81	  col = mix(col, vc, vein);
82	  // reflective highlights: soft white sheen patches drifting with the flow + the grazing-angle reflection far ahead
83	  float sh = sin(sf * 0.31 + u * 2.2 + 0.7) * sin(sf * 0.13 - u * 1.1 + 0.4);
84	  col += vec3(0.85, 0.95, 1.0) * 0.22 * pow(max(sh, 0.0), 3.0) * (0.5 + body);
85	  col += fres * 0.18 * vec3(0.9, 0.88, 1.0);
86	  // star glints twinkling on the veins
87	  float gl = max(a.b, b.b * 0.8) * (0.35 + 0.65 * pow(0.5 + 0.5 * sin(t * 8.0 + ls.x * 6.1 + sf * 2.3), 3.0));
88	  col += vec3(0.85, 0.97, 1.0) * gl * uW30A.w;
89	  // soft swirl / ring ripples spreading outward round Benny (uBen = lateral, s; one-armed spiral = swirl)
90	  vec2 dB = ls - uBen;
91	  float d = length(dB);
92	  if (uW30B.z > 0.0 && d < 2.6) {
93	    float ph = d * 6.2831853 / 0.42 - t * 3.2 + atan(dB.y, dB.x);
94	    float rg = pow(0.5 + 0.5 * cos(ph), 5.0) * smoothstep(2.6, 0.9, d) * smoothstep(0.45, 0.8, d);
95	    col = mix(col, vec3(0.86, 1.0, 1.0), rg * uW30B.z);
96	  }
97	  col = mix(col, old, uW30B.w);
98	  return mix(old, clamp(col, 0.0, 1.0), smoothstep(uW30C.x, uW30C.y, dAp));
99	}
100	#endif
101	`;
