103	const num = (qs: URLSearchParams | null, k: string, d: number) => { const v = qs?.get(k); return v !== null && v !== undefined && v !== '' && Number.isFinite(Number(v)) ? Number(v) : d; };
104	const pair = (qs: URLSearchParams | null, k: string, d: [number, number]): [number, number] => {
105	  const p = (qs?.get(k) ?? '').split(',').map(Number);
106	  return p.length === 2 && p.every(Number.isFinite) ? [p[0], p[1]] : d;
107	};
