109	/** `&w30=1`: switch the river floor material (m06_floor and the m06leg ribbon share it) to the r30 rainbow water. Returns whether on. */
110	export async function setupW30(mat: THREE.ShaderMaterial, qs: URLSearchParams | null, flow: boolean): Promise<boolean> {
111	  if (qs?.get('w30') !== '1' || !flow) return false;
112	  const t = await new THREE.TextureLoader().loadAsync(new URL('../../assets/textures/match06/tile_w30veins.png', import.meta.url).href);
113	  t.colorSpace = THREE.NoColorSpace; t.wrapS = t.wrapT = THREE.RepeatWrapping; t.anisotropy = 8;
114	  t.minFilter = THREE.LinearMipmapLinearFilter;
115	  const [ta, tb] = pair(qs, 'w30t', [2.2, 3.8]), [sa, sb] = pair(qs, 'w30st', [0.02, 0.6]), [ea, eb] = pair(qs, 'w30e', [0.36, 1.0]);
116	  Object.assign(mat.uniforms, {
117	    uW30T: { value: t },
118	    uW30A: { value: new THREE.Vector4(num(qs, 'w30f', 2.2), num(qs, 'w30v', 1), num(qs, 'w30rb', 1), num(qs, 'w30sp', 1)) },
119	    uW30B: { value: new THREE.Vector4(ta, tb, num(qs, 'w30rip', 0.55), num(qs, 'w30old', 0)) },
120	    uW30C: { value: new THREE.Vector4(sa, sb, ea, eb) },
121	  });
122	  mat.defines = { ...(mat.defines ?? {}), W30: '' };
123	  mat.needsUpdate = true;
124	  console.info('[match06] w30 rainbow water', { tile: [ta, tb], start: [sa, sb], band: [ea, eb] });
125	  return true;
126	}
